  "check_code": "import sqlite3
from pathlib import Path


SUBMISSION_ID = "SUB-OBM-2025-09-014"
TARGET_STEP_ID = "APR-OBM-2025-09-014-02"


def _db(ws):
    return Path(ws).resolve().parent / "system" / "obm_submission_workflow" / "state.db"


def _connect(ws):
    con = sqlite3.connect(_db(ws))
    con.row_factory = sqlite3.Row
    return con


def check_rejection_recorded(ws):
    with _connect(ws) as con:
        step = con.execute(
            "SELECT approval_step_id, submission_id, step_sequence, decision, decision_at, decision_comment "
            "FROM approval_steps WHERE approval_step_id = ?",
            (TARGET_STEP_ID,),
        ).fetchone()
        package = con.execute(
            "SELECT submission_status, submitted_at FROM submission_packages WHERE submission_id = ?",
            (SUBMISSION_ID,),
        ).fetchone()
    ok = (
        step is not None
        and package is not None
        and step["submission_id"] == SUBMISSION_ID
        and step["step_sequence"] == 2
        and step["decision"] == "REJECTED"
        and step["decision_at"]
        and step["decision_comment"]
        and step["decision_comment"].strip()
        and package["submission_status"] == "REJECTED"
        and package["submitted_at"] is None
    )
    return {"score": 1 if ok else 0, "detail": "OBM step 2 is REJECTED and the package is not submitted." if ok else "Pending OBM rejection state is incomplete or incorrect."}


def check_unchanged_package_evidence(ws):
    expected_artifacts = {
        "ART-OBM-2025-09-014-01": ("READY", "v1.3", "sha256:8e1c0a91f0b44a71b21d"),
        "ART-OBM-2025-09-014-04": ("PENDING", "v1.0", "sha256:da11f6e1c00a4d220bc8"),
        "ART-OBM-2025-09-014-02": ("READY", "v1.1", "sha256:1b7d3cc8e4aa902f7e42"),
        "ART-OBM-2025-09-014-03": ("READY", "v1.0", "sha256:6c9b3c20d1e8790b9ca4"),
    }
    expected_checks = {
        "CERT-OBM-2025-09-014-04": ("REFRESHED_ANALYTICS_ACTUAL", 12345600, "PENDING"),
        "CERT-OBM-2025-09-014-05": ("ACTION_OPEN_COUNT", 2, "CERTIFIED"),
        "CERT-OBM-2025-09-014-01": ("YTD_ACTUAL_EXPENDITURE", 8250000, "CERTIFIED"),
        "CERT-OBM-2025-09-014-06": ("TRANSMITTAL_SIGNATURE", 1, "PENDING"),
        "CERT-OBM-2025-09-014-03": ("APPROVED_ALLOTMENT", 15000000, "CERTIFIED"),
        "CERT-OBM-2025-09-014-02": ("YTD_ACTUAL_EXPENDITURE", 3932100, "CERTIFIED"),
    }
    with _connect(ws) as con:
        artifacts = {
            row["artifact_id"]: (row["artifact_status"], row["document_version"], row["checksum"])
            for row in con.execute("SELECT artifact_id, artifact_status, document_version, checksum FROM package_artifacts WHERE submission_id = ?", (SUBMISSION_ID,))
        }
        checks = {
            row["certification_id"]: (row["check_name"], row["certified_value_cents"], row["certification_status"])
            for row in con.execute("SELECT certification_id, check_name, certified_value_cents, certification_status FROM certification_checks WHERE submission_id = ?", (SUBMISSION_ID,))
        }
        prior = con.execute("SELECT decision, decision_comment, artifact_id FROM approval_steps WHERE approval_step_id = 'APR-OBM-2025-09-014-01'").fetchone()
    ok = artifacts == expected_artifacts and checks == expected_checks and tuple(prior) == ("APPROVED", "DWM budget control review complete.", "ART-OBM-2025-09-014-01")
    return {"score": 1 if ok else 0, "detail": "Unrelated package evidence and prior approval are unchanged." if ok else "An unrelated artifact, certification, or prior approval was changed."}
",
